const D = { density: .55, weave: .5, energy: .62, speed: 1, families: 3, scale: 1, hue: 210, x: .5, y: .5, style: 'neon', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1) * 60;
  S.fj = [];
  for (let f = 0; f < 4; f++) S.fj.push({
    dx: (fr(10 + f) - .5) * 0.14,
    dy: (fr(20 + f) - .5) * 0.14,
    rj: 0.80 + fr(30 + f) * 0.34,
    kj: (fr(40 + f) - .5) * 0.9,
    ph: fr(50 + f) * 6.283
  });
}

const u = Math.min(width, height);
const style = P.style;
const t = K.t * (0.15 + P.speed * 0.55);
const sec = K.section | 0, inten = K.intensity;
const fam = Math.max(1, Math.min(4, P.families | 0));
const Mn = Math.round(64 + P.density * 168);                 // nail count 64..232
const perFam = Math.min(Mn, Math.max(24, Math.floor(560 / fam))); // cap total lines
const kBase = 2 + P.weave * 5.2;                             // envelope order 2..7.2
const cx = P.x * width, cy = P.y * height;
const baseR = 0.60 * u * P.scale;
const expo = Math.min(1.9, 0.5 + P.energy * 0.9 + inten * 0.3 + A.rms * 0.6);
const gRot = t * 0.10;
const av = P.alpha / 100;
const baseHue0 = (P.hue + sec * 16) % 360;

// background: dark tone, never near-black (opaque mode only)
let bgh, bgs, bgb, ghue, gsat;
if (style === 'gold-silk') { bgh = 32; bgs = 55; bgb = 6; ghue = 40; gsat = 45; }
else if (style === 'blueprint') { bgh = 212; bgs = 62; bgb = 13; ghue = 205; gsat = 55; }
else if (style === 'mono') { bgh = 0; bgs = 0; bgb = 5; ghue = 0; gsat = 0; }
else if (style === 'rainbow-rose') { bgh = (P.hue + 220) % 360; bgs = 30; bgb = 7; ghue = baseHue0; gsat = 40; }
else { bgh = (P.hue + 205) % 360; bgs = 42; bgb = 8; ghue = baseHue0; gsat = 42; } // neon
if (P.alpha >= 100) background(bgh, bgs, bgb);

// soft central glow — fills frame, lifts luminance floor
push(); blendMode(ADD); noStroke();
const breathe = 0.6 + 0.4 * Math.sin(K.t * 0.35) + K.swell * 0.2;
for (let r = 0; r < 3; r++) {
  const rr = u * (1.35 - r * 0.34) * (0.7 + P.scale * 0.3);
  fill(ghue, gsat, 100, (3.4 - r * 0.8) * expo * av * breathe);
  ellipse(cx, cy, rr * 2, rr * 2);
}
blendMode(BLEND); pop();

// thread families
push();
blendMode(ADD);
translate(cx, cy);
rotate(gRot);
const w1 = Math.max(1.3, u * 0.0055) * (0.9 + P.energy * 0.4);
const w2 = Math.max(0.6, u * 0.0020);
const kick = 1 + A.bass * 0.5 + K.pulse * 0.15;
const a1a = Math.min(14, (5 + P.energy * 7) * expo * av * (style === 'blueprint' ? 0.6 : 1));
const a2a = Math.min(34, (12 + P.energy * 16) * expo * av * kick);
const TWO = 6.28318530718;

for (let f = 0; f < fam; f++) {
  const j = S.fj[f];
  const fcx = j.dx * u, fcy = j.dy * u;
  const R = baseR * j.rj;
  const k = kBase + f * 0.9 + j.kj * 0.5 + Math.sin(t * 0.23 + j.ph) * 0.6 + sec * 0.12;
  const off = t * (3.0 + f * 0.7) + j.ph * 4.0;      // continuous drift -> envelope breathes
  const famHue = (P.hue + f * 54 + S.hoff * 0.3 + sec * 16) % 360;
  const step = Mn / perFam;
  const isBP = style === 'blueprint';
  for (let n = 0; n < perFam; n++) {
    const i = n * step;
    const ang1 = TWO * i / Mn;
    const ang2 = TWO * (i * k + off) / Mn;
    const x1 = fcx + Math.cos(ang1) * R, y1 = fcy + Math.sin(ang1) * R;
    const x2 = fcx + Math.cos(ang2) * R, y2 = fcy + Math.sin(ang2) * R;
    let h, s, b2core;
    if (style === 'mono') { h = 0; s = 0; b2core = 100; }
    else if (style === 'gold-silk') {
      const chord = Math.abs(Math.sin((ang2 - ang1) * 0.5));
      h = 34 + Math.sin(ang1 * 3 + t) * 9; s = 78 - chord * 34; b2core = 100;
    }
    else if (isBP) { h = 200; s = 82; b2core = 100; }
    else if (style === 'rainbow-rose') { h = (P.hue + (i / Mn) * 720 + f * 40) % 360; s = 92; b2core = 100; }
    else { h = famHue; s = 88; b2core = 100; } // neon
    // pass 1 — wide dim halo (colored)
    strokeWeight(w1); stroke(h, s, 58, a1a); line(x1, y1, x2, y2);
    // pass 2 — thin bright core (white-hot for glow)
    strokeWeight(w2); stroke(h, s * 0.5, b2core, a2a); line(x1, y1, x2, y2);
    if (isBP) { strokeWeight(w2 * 1.6); stroke(190, 40, 100, a2a * 0.9); point(x1, y1); }
  }
  if (isBP) { noFill(); strokeWeight(0.8); stroke(200, 70, 90, 10 * av); ellipse(fcx, fcy, R * 2, R * 2); }
}
blendMode(BLEND);
pop();

// audio treble sparkle on the caustic — partial, never full-frame
if ((A.treble > 0.02 || A.rms > 0.02) && P.alpha > 5) {
  push(); blendMode(ADD); noStroke();
  const sp = (A.treble * 0.6 + A.rms * 0.3) * P.energy * av;
  fill((baseHue0 + 40) % 360, 30, 100, sp * 20);
  ellipse(cx, cy, u * 0.5, u * 0.5);
  blendMode(BLEND); pop();
}
